  function expenseTable(rows,includeActions,locked=false){const s=snap();return`<div class="panel table-wrap"><table class="data-table"><thead><tr><th>${esc(t('seaVibe.common.date','التاريخ'))}</th><th>${esc(t('seaVibe.expense.item','المصروف'))}</th><th>${esc(t('seaVibe.expense.amount','القيمة'))}</th><th>${esc(t('seaVibe.expense.payment','طريقة الدفع'))}</th><th>${esc(t('seaVibe.common.notes','الملاحظات'))}</th><th>${esc(t('seaVibe.expense.attachments','المرفقات'))}</th>${includeActions?`<th>${esc(t('seaVibe.common.actions','الإجراءات'))}</th>`:''}</tr></thead><tbody>${rows.length?rows.map(e=>{const at=s.attachments.filter(a=>a.expenseId===e.id);return`<tr><td>${esc(dateText(e.date))}</td><td>${esc(expenseName(e))}</td><td class="sea-vibe-money">${esc(money(e.amount))}</td><td>${esc(refName(findRef(s.paymentMethods,e.paymentMethodId))||'—')}</td><td>${esc(e.notes||'—')}</td><td>${at.length?`<button type="button" class="secondary-btn" data-sv-attachment="${esc(at[0].path)}">${at.length}</button>`:'—'}</td>${includeActions?`<td>${e.systemGenerated?esc(t('seaVibe.expense.system','نظامي')):locked?esc(t('seaVibe.expense.locked','مغلق')):`<button type="button" class="secondary-btn" data-sv-delete-expense="${esc(e.id)}" data-permission-screen="seaVibeExpenseNew" data-permission-action="delete">${esc(t('seaVibe.common.delete','حذف'))}</button>`}</td>`:''}</tr>`}).join(''):`<tr><td colspan="${includeActions?7:6}" class="empty-cell">${esc(t('seaVibe.expense.empty','لا توجد مصروفات.'))}</td></tr>`}</tbody></table></div>`;}

