  function setExpenseEditingState(groupId='',returnView=''){editingExpenseGroupId=String(groupId||'');expenseReturnView=String(returnView||'');const groupField=$('seaVibeExpenseMovementGroupId'),returnField=$('seaVibeExpenseReturnView');if(groupField)groupField.value=editingExpenseGroupId;if(returnField)returnField.value=expenseReturnView;setExpenseSubmitMode(!!editingExpenseGroupId);}
  function currentExpenseEditingState(){const groupId=String($('seaVibeExpenseMovementGroupId')?.value||editingExpenseGroupId||'').trim(),returnView=String($('seaVibeExpenseReturnView')?.value||expenseReturnView||'').trim();if(groupId!==editingExpenseGroupId||returnView!==expenseReturnView){editingExpenseGroupId=groupId;expenseReturnView=returnView;}return{groupId,returnView};}
  function syncExpenseScope(){const scope=$('seaVibeExpenseScope')?.value||'trip',tripField=$('seaVibeExpenseTripField'),assetField=$('seaVibeExpenseAssetField'),tripSelect=$('seaVibeExpenseTrip'),assetSelect=$('seaVibeExpenseAsset'),scopeDisplay=$('seaVibeExpenseScopeDisplay');tripField?.classList.toggle('hidden',scope!=='trip');assetField?.classList.toggle('hidden',scope!=='asset');if(scopeDisplay)scopeDisplay.value=expenseScopeText(scope);if(tripSelect)tripSelect.required=scope==='trip';if(assetSelect)assetSelect.required=scope==='asset';syncTripExpenseDates();}
