  function collectExpenses(){const scope=$('seaVibeExpenseScope').value,tripId=scope==='trip'?$('seaVibeExpenseTrip').value:'',assetId=scope==='asset'?$('seaVibeExpenseAsset').value:'',trip=scope==='trip'?selectedExpenseTrip():null;if(scope==='trip'&&!tripId)throw new Error(t('seaVibe.validation.tripRequired','اختر رحلة مفتوحة.'));if(scope==='asset'&&!assetId)throw new Error(t('seaVibe.validation.assetRequired','اختر أصلًا.'));return[...document.querySelectorAll('#seaVibeExpenseRows [data-sv-expense-row]')].map(row=>{const catalogId=row.querySelector('[data-field="catalogId"]').value;if(!catalogId)throw new Error(t('seaVibe.validation.expenseItemRequired','اختر المصروف.'));return{id:row.dataset.expenseId||'',scope,tripId,assetId,catalogId,amount:Number(row.querySelector('[data-field="amount"]').value||0),paymentMethodId:row.querySelector('[data-field="paymentMethodId"]').value,date:scope==='trip'?(trip?.date||''):row.querySelector('[data-field="date"]').value,notes:row.querySelector('[data-field="notes"]').value,file:row.querySelector('[data-field="file"]').files?.[0]||null};});}

