  function treasuryVoucherErrorText(value){
    const raw=String(value||'');
    if(raw.includes('SEA_VIBE_VOUCHER_ONLINE_REQUIRED'))return t('seaVibe.treasury.voucherOnlineRequired','An internet connection is required to save or edit treasury vouchers.');
    if(raw.includes('SEA_VIBE_VOUCHER_REQUIRED_FIELDS')||raw.includes('SEA_VIBE_VOUCHER_DATE_REQUIRED')||raw.includes('SEA_VIBE_VOUCHER_AMOUNT_REQUIRED')||raw.includes('SEA_VIBE_VOUCHER_DESCRIPTION_REQUIRED')||raw.includes('SEA_VIBE_VOUCHER_COUNTERPART_REQUIRED'))return t('seaVibe.treasury.voucherRequired','Complete the date, counterpart account, amount, and description.');
    if(raw.includes('SEA_VIBE_ACCOUNT_POSTING_REQUIRED'))return t('seaVibe.accounts.validationFailed','Unable to save the account. Review its code, parent, type, and status.');
    if(raw.includes('SEA_VIBE_VOUCHER_COUNTERPART_TREASURY_NOT_ALLOWED'))return t('seaVibe.treasury.selectCounterpart','Select counterpart account');
    if(raw.includes('SEA_VIBE_VOUCHER_ATTACHMENT_TOO_LARGE'))return t('seaVibe.treasury.attachmentHint','PDF, JPG, PNG or WEBP — max 5 MB');
    if(raw.includes('SEA_VIBE_VOUCHER_ATTACHMENT_TYPE_INVALID'))return t('seaVibe.treasury.attachmentTypeInvalid','Unsupported attachment type. Use PDF, JPG, PNG, or WEBP.');
    return uiMessage(raw);
  }
