  function journalErrorText(value){const raw=String(value||'');if(raw.includes('SEA_VIBE_JOURNAL_ONLINE_REQUIRED'))return t('seaVibe.journal.onlineRequired','An internet connection is required to save financial journal entries.');if(raw.includes('SEA_VIBE_JOURNAL_UNBALANCED'))return t('seaVibe.journal.unbalanced','The journal cannot be posted until total debit equals total credit.');if(raw.includes('SEA_VIBE_JOURNAL_TWO_LINES_REQUIRED'))return t('seaVibe.journal.twoLines','Add at least two accounting lines before posting.');if(raw.includes('SEA_VIBE_JOURNAL_ACCOUNT_REQUIRED')||raw.includes('SEA_VIBE_JOURNAL_POSTING_ACCOUNT_REQUIRED'))return t('seaVibe.journal.accountRequired','Select a valid posting account for each line.');if(raw.includes('SEA_VIBE_JOURNAL_ONE_SIDE_ONLY'))return t('seaVibe.journal.oneSideOnly','Enter an amount on either debit or credit only for each line.');if(raw.includes('SEA_VIBE_JOURNAL_AMOUNT_REQUIRED'))return t('seaVibe.journal.amountRequired','Enter a debit or credit amount for each line before posting.');if(raw.includes('SEA_VIBE_JOURNAL_POSTED_LOCKED'))return t('seaVibe.journal.postedLocked','A posted journal is locked and cannot be edited.');if(raw.includes('SEA_VIBE_JOURNAL_ATTACHMENT_INVALID'))return t('seaVibe.journal.attachmentInvalid','The attachment type is unsupported or exceeds 10 MB.');if(raw.includes('SEA_VIBE_JOURNAL_VAT_ACCOUNT_REQUIRED'))return t('seaVibe.journal.vatAccountMissing','VAT account 2101 is unavailable.');return uiMessage(raw);}
